// Driver: launch the real auth server, drive the full OAuth flow, print the token.
import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';

const REPO = '/Users/kaszperek/repos/happening';
const ISSUER = 'http://127.0.0.1:4000';
const RESOURCE = 'http://127.0.0.1:3001/mcp';
const REDIRECT = 'http://127.0.0.1:8321/callback';
const BRIDGE = 'http://127.0.0.1:4001';
const BRIDGE_KEY = 'slice1-loopback-bridge-key';
const COMMONCAL = 'http://127.0.0.1:4002';
const SCOPE = 'commoncal.calendar.metadata.read commoncal.event.read.basic';

const env = {
  ...process.env,
  LAB_ISSUER: ISSUER,
  LAB_RESOURCE_URL: RESOURCE,
  LAB_COMMONCAL_URL: COMMONCAL,
  LAB_LOOPBACK_REDIRECT: REDIRECT,
  LAB_BRIDGE_KEY: BRIDGE_KEY,
  DATABASE_URL: 'postgres://oidc:oidc-lab-only@127.0.0.1:5432/oidc',
  AUTH_PUBLIC_BIND: '127.0.0.1',
  AUTH_PRIVATE_BIND: '127.0.0.1',
  AUTH_PUBLIC_PORT: '4000',
  AUTH_PRIVATE_PORT: '4001',
  AUTH_JWKS_FILE: `${REPO}/slice1-lab/auth-server/test-jwks.json`,
  AUTH_SIGNING_KID: 'slice1-test-rs256',
};

const server = spawn('node', [`${REPO}/slice1-lab/auth-server/src/server.mjs`], {
  env,
  stdio: ['ignore', 'pipe', 'pipe'],
});
let serverLog = '';
server.stdout.on('data', (d) => (serverLog += d.toString()));
server.stderr.on('data', (d) => (serverLog += d.toString()));

async function waitForReady() {
  for (let i = 0; i < 100; i++) {
    try {
      const r = await fetch(`${ISSUER}/health`);
      if (r.ok) return true;
    } catch {}
    await sleep(100);
  }
  return false;
}

function b64url(buf) { return Buffer.from(buf).toString('base64url'); }
import { createHash, randomBytes } from 'node:crypto';
const challenge = b64url(createHash('sha256').update('verifier-abc-123').digest());
const state = randomBytes(16).toString('hex');

async function main() {
  const ready = await waitForReady();
  if (!ready) {
    console.error('SERVER NOT READY');
    console.error(serverLog);
    server.kill('SIGTERM');
    process.exit(2);
  }

  // 1. DCR
  const dcr = await fetch(`${ISSUER}/reg`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({
      client_name: 'rust-integration-test',
      redirect_uris: [REDIRECT],
      grant_types: ['authorization_code', 'refresh_token'],
      response_types: ['code'],
      token_endpoint_auth_method: 'none',
      scope: SCOPE,
    }),
  });
  const dcrBody = await dcr.json();
  if (dcr.status !== 201 || !dcrBody.client_id) {
    console.error('DCR FAILED', dcr.status, JSON.stringify(dcrBody));
    server.kill('SIGTERM');
    process.exit(3);
  }
  const clientId = dcrBody.client_id;

  // 2. GET /auth -> follow redirects manually
  const authUrl = `${ISSUER}/auth?${new URLSearchParams({
    response_type: 'code',
    client_id: clientId,
    redirect_uri: REDIRECT,
    scope: SCOPE,
    state,
    code_challenge: challenge,
    code_challenge_method: 'S256',
    resource: RESOURCE,
  })}`;

  let code = null;
  let lastLocation = null;
  // Follow the redirect chain, driving the bridge at each consent step.
  for (let hop = 0; hop < 12; hop++) {
    let url = authUrl;
    let res;
    // On subsequent hops we follow the Location.
    if (hop === 0) {
      res = await fetch(url, { redirect: 'manual' });
    } else {
      res = await fetch(lastLocation, { redirect: 'manual' });
    }
    const loc = res.headers.get('location');
    lastLocation = loc;
    const body = await res.text();

    if (loc && loc.includes('/consent?handoff=')) {
      // CommonCal consent step: extract handoff, drive the bridge.
      const handoff = new URL(loc).searchParams.get('handoff');
      // Look up the interaction to see the prompt.
      const lookup = await fetch(`${BRIDGE}/internal/interactions/${encodeURIComponent(handoff)}`, {
        headers: { authorization: `Bearer ${BRIDGE_KEY}` },
      });
      const view = await lookup.json();
      const kind = view.prompt === 'login' ? 'login' : 'consent';
      const decideBody = { kind };
      if (kind === 'login') decideBody.subject = '1';
      const decide = await fetch(`${BRIDGE}/internal/interactions/${encodeURIComponent(handoff)}`, {
        method: 'PUT',
        headers: { authorization: `Bearer ${BRIDGE_KEY}`, 'content-type': 'application/json' },
        body: JSON.stringify(decideBody),
      });
      const decideRes = await decide.json();
      if (!decideRes.resumeUrl) {
        console.error('DECIDE FAILED', decide.status, JSON.stringify(decideRes));
        server.kill('SIGTERM');
        process.exit(4);
      }
      // Continue to the resumeUrl on the next hop.
      continue;
    }

    if (loc && loc.startsWith(REDIRECT)) {
      // Final redirect with the code.
      const u = new URL(loc);
      code = u.searchParams.get('code');
      break;
    }

    if (loc) {
      // Some other redirect (e.g., /interaction/{uid}); follow it.
      continue;
    }

    // No location; inspect body for errors.
    console.error('NO LOCATION at hop', hop, 'status', res.status, 'body', body.slice(0, 500));
    break;
  }

  if (!code) {
    console.error('NO CODE OBTAINED');
    console.error('lastLocation', lastLocation);
    console.error(serverLog.slice(-2000));
    server.kill('SIGTERM');
    process.exit(5);
  }

  // 3. Token exchange
  const tokenRes = await fetch(`${ISSUER}/token`, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'authorization_code',
      code,
      redirect_uri: REDIRECT,
      client_id: clientId,
      code_verifier: 'verifier-abc-123',
    }).toString(),
  });
  const tokenBody = await tokenRes.json();
  server.kill('SIGTERM');

  if (tokenRes.status !== 200 || !tokenBody.access_token) {
    console.error('TOKEN EXCHANGE FAILED', tokenRes.status, JSON.stringify(tokenBody));
    process.exit(6);
  }

  // Decode the payload for inspection.
  const payload = JSON.parse(Buffer.from(tokenBody.access_token.split('.')[1], 'base64url').toString());
  console.log(JSON.stringify({
    ok: true,
    issuer: ISSUER,
    resource: RESOURCE,
    client_id: clientId,
    access_token: tokenBody.access_token,
    claims: payload,
  }));
  process.exit(0);
}

main().catch((e) => {
  console.error('DRIVER ERROR', e);
  server.kill('SIGTERM');
  process.exit(9);
});

