    shuttingDown = true;
    server.kill('SIGTERM');
    process.exit(0);
  };
  process.once('SIGTERM', shutdown);
  process.once('SIGINT', shutdown);
  setTimeout(shutdown, 120_000).unref?.();
  await new Promise(() => {});
}

