#[tokio::test]
async fn phase3_real_auth_server_token_validates() {
    let helper = format!(
        "{}/tests/real_auth_server_token.mjs",
        env!("CARGO_MANIFEST_DIR")
    );

    let mut child = match tokio::process::Command::new("node")
        .arg(&helper)
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .spawn()
    {
        Ok(child) => child,
        Err(e) => {
            eprintln!("skip: cannot spawn node helper: {e}");
            return;
        }
    };

    // Read the helper's stdout until we get the JSON token line (or it exits).
    // The helper keeps the auth server alive after printing the token so the
    // validator can fetch discovery + JWKS from the live server.
    use tokio::io::{AsyncBufReadExt, BufReader};
    let stdout = child.stdout.take().expect("stdout piped");
    let mut lines = BufReader::new(stdout).lines();

    let token_line = tokio::time::timeout(
        std::time::Duration::from_secs(90),
        async {
            while let Some(line) = lines.next_line().await {
                let line = line.unwrap_or_default();
                if line.trim_start().starts_with('{') {
                    return Some(line);
                }
            }
            None
        },
    )
    .await
    .unwrap_or(None);

    let Some(line) = token_line else {
        // Helper exited without producing a token. Capture stderr for diagnostics.
        let _ = child.kill().await;
        let output = child.wait_with_output().await.unwrap_or_default();
        let stderr = String::from_utf8_lossy(&output.stderr);
        if output.status.code() == Some(100) {
            eprintln!("skip: real auth server environment unavailable (PostgreSQL)");
        } else {
            panic!("real auth server helper produced no token: {stderr}");
        }
        return;
    };

    let parsed: serde_json::Value =
        serde_json::from_str(&line).expect("helper output must be valid JSON");
    let token = parsed["access_token"]
        .as_str()
        .expect("access_token present")
        .to_string();
    let issuer = parsed["issuer"].as_str().expect("issuer present").to_string();
    let resource = parsed["resource"]
        .as_str()
        .expect("resource present")
        .to_string();
    let client_id = parsed["client_id"]
        .as_str()
        .expect("client_id present")
        .to_string();

    // Validate the token while the auth server is still alive.
    let validator = TokenValidator::new();
    let result = validator
        .validate(&token, &issuer, &resource)
        .await
        .expect("token issued by the real auth server must validate");

    // Standard claims parsed correctly.
    assert_eq!(result.user_id, 1, "numeric sub must parse to the CommonCal user id");
    assert_eq!(result.oauth_client_id, client_id);
    assert!(
        result.scopes.contains(&"commoncal.calendar.metadata.read".to_string()),
        "granted scope must be present: {:?}",
        result.scopes
    );
    assert!(
        result.scopes.contains(&"commoncal.event.read.basic".to_string()),
        "granted scope must be present: {:?}",
        result.scopes
    );
    assert!(!result.token_id.is_empty(), "jti must be present");
    assert!(
        result.expires_at > 0,
        "exp must be a positive Unix timestamp"
    );

    // Clean up: kill the helper (which tears down the auth server).
    let _ = child.kill().await;
    let _ = child.wait().await;
}

