input.content:
// Check: does the helper keep the auth server alive after printing the token?
import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';

const helper = '/Users/kaszperek/repos/happening/mcp-server/tests/real_auth_server_token.mjs';
const child = spawn('node', [helper], { stdio: ['ignore', 'pipe', 'pipe'] });
let stdout = '';
let stderr = '';
child.stdout.on('data', (d) => (stdout += d.toString()));
child.stderr.on('data', (d) => (stderr += d.toString()));

// Wait for the token line.
for (let i = 0; i < 100; i++) {
  if (stdout.includes('"access_token"')) break;
  await sleep(100);
}

console.log('=== token received:', stdout.includes('"access_token"'));

// Check if the helper is still alive.
let alive = true;
try {
  process.kill(child.pid, 0);
} catch {
  alive = false;
}
console.log('=== helper still alive:', alive);

// Check if the auth server is reachable.
try {
  const r = await fetch('http://127.0.0.1:4000/.well-known/oauth-authorization-server');
  console.log('=== auth server reachable:', r.status);
  const body = await r.text();
  console.log('=== discovery body (first 200):', body.slice(0, 200));
} catch (e) {
  console.log('=== auth server NOT reachable:', e.message);
}

// Check if the helper is still alive after the fetch.
try {
  process.kill(child.pid, 0);
  console.log('=== helper still alive after fetch: true');
} catch {
  console.log('=== helper still alive after fetch: false');
}

// Kill the helper.
child.kill('SIGTERM');
await sleep(500);
console.log('=== stderr (tail):', stderr.slice(-500));
process.exit(0);

